const $=s=>document.querySelector(s), esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='scenario-meijin-v1', uid=()=>crypto.randomUUID(), today=()=>new Intl.DateTimeFormat('sv-SE',{timeZone:'Asia/Tokyo'}).format(new Date());
const initial={version:1,title:'余白の向こう',author:'',date:today(),draft:1,font:'Noto Serif JP',size:14,printSize:12,direction:'vertical',dark:false,rate:300,actionSeconds:5,cover:true,chapters:[{id:uid(),title:'帰り道',status:'見直し',text:'○海沿いのバス停（夕）\n　　　海からの風が、時刻表の端を揺らす。\n　　　澪（28）、古い封筒を手に立っている。\n\n澪「ここ、まだあったんだ」\n\n　　　ベンチに座る修司（32）。顔を上げる。\n修司「バス停？」\n澪「ううん。待つ場所」\n\n　　　遠くで、踏切の音。\n　　　澪、封筒を鞄にしまう。\n修司「乗るの？」\n澪「……もう一本、待つ」\n\n　　　二人の間を、風が通り抜ける。'},{id:uid(),title:'届かなかった手紙',status:'未着手',text:''},{id:uid(),title:'朝の光',status:'未着手',text:''}]};
let state=initial, active, composing=false, timer, dirty=false;
try{const raw=localStorage.getItem(KEY);if(raw)state=validate(JSON.parse(raw));}catch(e){setTimeout(()=>toast('保存データを読み込めません。バックアップから復元してください。'),500)}
active=state.chapters[0].id;
function validate(v){if(!v||!Array.isArray(v.chapters)||!v.chapters.length||v.chapters.some(c=>typeof c.text!=='string'||typeof c.title!=='string'))throw Error('形式が違います');return {...initial,...v,font:['Noto Serif JP','Noto Sans JP','Zen Old Mincho'].includes(v.font)?v.font:initial.font,size:Math.min(32,Math.max(14,Number(v.size)||14)),printSize:Math.min(18,Math.max(9,Number(v.printSize)||12)),rate:Math.max(60,Number(v.rate)||300),actionSeconds:Math.max(1,Number(v.actionSeconds)||5),chapters:v.chapters.map(c=>({...c,id:uid(),status:['完了','見直し','未着手'].includes(c.status)?c.status:'未着手'}))}}
const chapter=()=>state.chapters.find(c=>c.id===active);
function save(){clearTimeout(timer);try{localStorage.setItem(KEY,JSON.stringify(state));dirty=false;$('#saved').textContent='保存済み';}catch(e){$('#saved').textContent='保存失敗';toast('自動保存できません。バックアップを書き出してください。')}}
function changed(){dirty=true;$('#saved').textContent='保存中';clearTimeout(timer);timer=setTimeout(save,350)}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
function type(s){return /^[○◯〇]/.test(s.trimStart())?'scene':/^[^「\n]+「/.test(s.trimStart())?'dialogue':'action'}
function markup(s){return esc(s).replace(/[A-Za-z0-9]+/g,m=>m.length<=2?'<span class="tcy">'+m+'</span>':m)}
function paragraph(line){const kind=type(line);const p=document.createElement('p');p.className=line.trim()?kind:'';p.innerHTML=line?markup(kind==='action'?line.replace(/^[ \u3000]+/,''):line):'<br>';return p}
function renderText(){const ed=$('#editor');ed.replaceChildren(...chapter().text.split('\n').map(paragraph));$('#emptyHint').hidden=!!chapter().text;}
function readText(){const ed=$('#editor');return [...ed.childNodes].map(n=>{if(n.nodeType===3)return n.textContent;let t=n.innerText.replace(/\r/g,'').replace(/\n$/,'');return n.classList.contains('action')&&t.trim()?'　　　'+t.replace(/^[ \u3000]+/,''):t}).join('\n')}
function capture(){chapter().text=readText();$('#emptyHint').hidden=!!chapter().text;changed();stats()}
function apply(){document.body.classList.toggle('dark',state.dark);document.documentElement.style.setProperty('--font',`'${state.font}'`);document.documentElement.style.setProperty('--size',state.size+'px');$('#editor').classList.toggle('horizontal',state.direction==='horizontal');$('#direction').textContent=state.direction==='vertical'?'縦書き':'横書き'}
function render(){apply();$('#projectTitle').textContent=state.title;$('#breadcrumb').textContent=state.title+' / '+chapter().title;$('#chapterTitle').value=chapter().title;$('#chapterNumber').textContent='CHAPTER '+String(state.chapters.indexOf(chapter())+1).padStart(2,'0');$('#status').value=chapter().status;renderNav();renderText();stats()}
function renderNav(){const nav=$('#chapters');nav.replaceChildren();state.chapters.forEach((c,i)=>{const b=document.createElement('button');b.className=c.id===active?'active':'';b.innerHTML=`<span class="num">${String(i+1).padStart(2,'0')}</span><span class="name">${esc(c.title)}</span><span class="dot">${c.status==='完了'?'●':c.status==='見直し'?'◐':'○'}</span>`;b.onclick=()=>{save();active=c.id;render();document.body.classList.remove('mobilemenu')};nav.append(b)});const n=state.chapters.length,a=state.chapters.filter(c=>c.status==='完了').length,b=state.chapters.filter(c=>c.status==='見直し').length;$('#chart').style.background=`conic-gradient(#555 0 ${a/n*100}%,#aaa ${a/n*100}% ${(a+b)/n*100}%,#ddd ${(a+b)/n*100}% 100%)`;$('#percent').textContent=Math.round(a/n*100)+'%';$('#progressText').textContent=a+' / '+n+' 章';$('#legend').innerHTML=[['完了',a,'#555'],['見直し',b,'#aaa'],['未着手',n-a-b,'#ddd']].map(([t,n,c])=>`<div><i style="background:${c}"></i>${t}　${n}</div>`).join('')}
function estimate(text){let speech=0,actions=0;for(const l of text.split('\n')){if(type(l)==='dialogue')speech+=Array.from(l.slice(l.indexOf('「')+1).replace(/[」\s]/g,'')).length;else if(l.trim()&&type(l)==='action')actions++}return speech/state.rate*60+actions*state.actionSeconds}
function stats(){const all=state.chapters.map(c=>c.text).join('\n'), n=Array.from(chapter().text.replace(/\s/g,'')).length, total=Array.from(all.replace(/\s/g,'')).length, sec=estimate(all);$('#count').textContent=n.toLocaleString()+' 字 / 全体 '+total.toLocaleString()+' 字';$('#duration').textContent='推定尺 '+Math.floor(sec/60)+'分'+Math.round(sec%60)+'秒';$('#duration').title='セリフ '+state.rate+'字/分 ＋ ト書き '+state.actionSeconds+'秒/段落。演出により変わる目安です。';$('#issueCount').textContent=issues().length?'· '+issues().length:''}
function modal(title,html){$('#dialogTitle').textContent=title;$('#dialogBody').innerHTML=html;$('#dialog').showModal()}
$('#close').onclick=()=>$('#dialog').close();$('#dialog').addEventListener('click',e=>{if(e.target===$('#dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});
$('#editor').addEventListener('compositionstart',()=>composing=true);$('#editor').addEventListener('compositionend',()=>{composing=false;capture()});$('#editor').addEventListener('input',()=>{if(!composing)capture()});
$('#editor').addEventListener('blur',()=>{if(!composing){capture()}});
$('#editor').addEventListener('paste',e=>{e.preventDefault();document.execCommand('insertText',false,e.clipboardData.getData('text/plain'))});
$('#chapterTitle').oninput=e=>{chapter().title=e.target.value;$('#breadcrumb').textContent=state.title+' / '+chapter().title;renderNav();changed()};$('#status').onchange=e=>{chapter().status=e.target.value;renderNav();changed()};
$('#add').onclick=()=>{modal('新しい章','<label>章のタイトル</label><input id="newTitle" value="新しい章"><button class="primary" id="createChapter">追加する</button>');$('#createChapter').onclick=()=>{const c={id:uid(),title:$('#newTitle').value.trim()||'新しい章',status:'未着手',text:''};state.chapters.push(c);active=c.id;save();render();$('#dialog').close()}};
$('#project').onclick=()=>{modal('作品情報',`<label>作品名</label><input id="titleField" value="${esc(state.title)}"><label>著者</label><input id="authorField" value="${esc(state.author)}" placeholder="著者名"><label>作成日</label><input type="date" id="dateField" value="${esc(state.date)}"><label>バージョン（稿数）</label><input id="draftField" type="number" min="1" value="${Number(state.draft)||1}"><button class="primary" id="saveMeta">保存する</button>`);$('#saveMeta').onclick=()=>{state.title=$('#titleField').value||'無題';state.author=$('#authorField').value;state.date=$('#dateField').value;state.draft=Math.max(1,Number($('#draftField').value)||1);save();render();$('#dialog').close()}};
$('#settings').onclick=()=>{modal('文字設定',`<label>Google Fonts 日本語フォント</label><select id="fontField">${['Noto Serif JP','Noto Sans JP','Zen Old Mincho'].map(f=>`<option ${state.font===f?'selected':''}>${f}</option>`).join('')}</select><label>画面の文字サイズ（px）</label><input id="sizeField" type="number" min="14" max="32" value="${state.size}"><label>印刷の文字サイズ（pt）</label><input id="printField" type="number" min="9" max="18" value="${state.printSize}"><label>1分間に話すセリフの文字数</label><p>300なら、セリフ300文字を約1分として計算します。</p><input id="rateField" type="number" min="60" max="1000" value="${state.rate}"><label>ト書き1段落の映像時間（秒）</label><p>5なら、動作や状況の1段落を約5秒として加算します。</p><input id="actionField" type="number" min="1" max="120" value="${state.actionSeconds}"><p>短い英数字（1〜2字）は縦中横にします。変換中の入力を守り、段落の組版は入力欄を離れた際に整えます。フォントの初回取得には通信が必要です。</p><button class="primary" id="saveSettings">適用する</button>`);$('#saveSettings').onclick=()=>{state.font=$('#fontField').value;state.size=Math.max(14,Math.min(32,Number($('#sizeField').value)||14));state.printSize=Math.max(9,Math.min(18,Number($('#printField').value)||12));state.rate=Math.max(60,Number($('#rateField').value)||300);state.actionSeconds=Math.max(1,Number($('#actionField').value)||5);save();apply();stats();$('#dialog').close()}};
$('#theme').onclick=()=>{state.dark=!state.dark;apply();changed()};$('#direction').onclick=()=>{state.direction=state.direction==='vertical'?'horizontal':'vertical';apply();changed()};$('#menu').onclick=()=>document.body.classList.toggle('mobilemenu');
function focusMode(){document.body.classList.toggle('focus');if(document.body.classList.contains('focus')){toast('Esc で集中モードを終了');$('#editor').focus()}}
$('#focus').onclick=focusMode;
function insert(kind){$('#editor').focus();const s=kind==='scene'?'○場所（時間）':kind==='action'?'　　　動作を書く。':'人物名「セリフ」';document.execCommand('insertText',false,'\n'+s+'\n');capture()}
document.querySelectorAll('[data-insert]').forEach(b=>{b.onmousedown=e=>e.preventDefault();b.onclick=()=>insert(b.dataset.insert)});
document.addEventListener('keydown',e=>{if(e.isComposing)return;if(e.key==='Escape')document.body.classList.remove('focus','mobilemenu');if((e.ctrlKey||e.metaKey)&&e.shiftKey&&e.key.toLowerCase()==='f'){e.preventDefault();focusMode()}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='s'){e.preventDefault();save();toast('保存しました')}if(e.altKey&&['1','2','3'].includes(e.key)){e.preventDefault();insert(['scene','action','dialogue'][Number(e.key)-1])}});
function issues(){const out=[];chapter().text.split('\n').forEach((line,i)=>{if(!line.trim())return;const t=type(line);const add=(message,fixed)=>out.push({i,line,message,fixed});if(t==='action'&&!/^　{3}/.test(line))add('ト書きの頭を３字下げます。','　　　'+line.trimStart());if(t==='dialogue'&&!line.includes('」'))add('セリフの閉じカギ括弧を追加します。',line+'」');if(/^「/.test(line.trim()))add('セリフの前に人物名を記してください。');if(/(?<!…)…(?!…)/.test(line))add('三点リーダーを２つにそろえます。',line.replace(/(?<!…)…(?!…)/g,'……'));if(t==='action'&&/(思った|感じた|悲しい|嬉しい|気がした)/.test(line))add('心情を、表情・動作・音として表せないか検討しましょう。');if(t==='action'&&/(だった|していた|しました)。?$/.test(line))add('ト書きは現在形で表せないか確認してください。')});return out}
function showCheck(){const list=issues(), groups=[...new Set(list.filter(x=>x.fixed).map(x=>x.message))];modal('自動修正',groups.length?groups.map((m,j)=>'<div class="issue">'+esc(m)+'<button data-group="'+j+'">一括修正（'+list.filter(x=>x.message===m).length+'件）</button></div>').join(''):'<p>修正する項目はありません。</p>');document.querySelectorAll('[data-group]').forEach(b=>b.onclick=()=>{const message=groups[Number(b.dataset.group)],lines=chapter().text.split('\n');list.filter(x=>x.message===message).forEach(x=>lines[x.i]=x.fixed);chapter().text=lines.join('\n');save();renderText();stats();$('#dialog').close();showCheck()})}$('#check').onclick=showCheck;
function download(content,ext,mime='text/plain;charset=utf-8'){const a=document.createElement('a'),u=URL.createObjectURL(new Blob([content],{type:mime}));a.href=u;a.download=(state.title.replace(/[\\/:*?"<>|]/g,'_')||'脚本')+'.'+ext;a.click();setTimeout(()=>URL.revokeObjectURL(u),30000)}
function exportText(md){let s=(md?'# ':'')+state.title+'\n\n'+[state.author,state.date,`第${state.draft}稿`].filter(Boolean).join(' / ')+'\n\n';return s+state.chapters.map((c,i)=>(md?'## ':'')+`${i+1}. ${c.title}\n\n`+c.text).join('\n\n'+(md?'---\n\n':'────────────────\n\n'))}
$('#backup').onclick=()=>download(JSON.stringify(state,null,2),'json','application/json');$('#import').onclick=()=>$('#file').click();$('#file').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{const s=await f.text();if(f.name.endsWith('.json')){const incoming=validate(JSON.parse(s));modal('バックアップを復元','<p>現在の作品をバックアップとしてダウンロードしてから、選択した作品を開きます。</p><button id="restore" class="primary">バックアップして復元</button>');$('#restore').onclick=()=>{download(JSON.stringify(state,null,2),'json','application/json');state=incoming;active=state.chapters[0].id;save();render();$('#dialog').close()}}else{const c={id:uid(),title:f.name.replace(/\.(txt|md)$/i,''),status:'未着手',text:s.replace(/^\uFEFF/,'').replace(/\r\n/g,'\n')};state.chapters.push(c);active=c.id;save();render();toast('新しい章として読み込みました')}}catch(err){toast('読み込めません。ファイル形式をご確認ください。')}e.target.value=''};
$('#export').onclick=()=>{modal('作品を書き出す',`<button class="exportoption" id="outPdf">PDFに保存<small>A4 横・縦書き・ページ番号付き</small></button><button class="exportoption" id="outPrint">印刷</button><label><input id="coverField" type="checkbox" ${state.cover?'checked':''}> 表紙を付ける</label><button class="exportoption" id="outTxt">テキスト .txt<small>柱・ト書き・セリフを保ったプレーンテキスト</small></button><button class="exportoption" id="outMd">Markdown .md<small>章見出し付き。プリプロ名人への受け渡しに</small></button><p>PDFは印刷画面の「PDFに保存」を選択してください。ブラウザ独自のヘッダー・フッターをオフにすると、原稿のフッターのみになります。TXT / MD 連携はファイルでの受け渡しです。</p>`);$('#outTxt').onclick=()=>download('\uFEFF'+exportText(false),'txt');$('#outMd').onclick=()=>download(exportText(true),'md','text/markdown;charset=utf-8');$('#outPrint').onclick=$('#outPdf').onclick=async()=>{state.cover=$('#coverField').checked;save();$('#dialog').close();await printProject()}};
async function printProject(){toast('印刷用のページを組んでいます…');await document.fonts.ready;const root=$('#printRoot');root.replaceChildren();document.documentElement.style.setProperty('--printsize',state.printSize+'pt');let number=0;
if(state.cover){const cover=document.createElement('section');cover.className='printpage cover';cover.innerHTML=`<h1>${esc(state.title)}</h1><p>${esc(state.author)}<br>${esc(state.date)}<br>第${esc(state.draft)}稿</p>`;root.append(cover)}
const measure=document.createElement('div');measure.style.cssText=`position:fixed;left:-10000px;top:0;width:257mm;height:170mm;writing-mode:vertical-rl;font-family:'${state.font}',serif;font-size:${state.printSize}pt;line-height:1.9;white-space:pre-wrap;line-break:strict;overflow-wrap:break-word;visibility:hidden;`;document.body.append(measure);
function emit(c){if(!measure.childNodes.length)return;number++;const page=document.createElement('section');page.className='printpage';const body=document.createElement('div');body.className='printbody';body.innerHTML=measure.innerHTML;page.append(body);const foot=document.createElement('div');foot.className='printfoot';foot.innerHTML=`<span>${esc(state.title)}</span><span>${esc(c.title)}</span><span>${number}</span>`;page.append(foot);root.append(page);measure.replaceChildren()}
for(const c of state.chapters){for(const line of c.text.split('\n')){let p=paragraph(line);p.style.margin='0 0 0 .6em';measure.append(p);if(measure.scrollWidth>measure.clientWidth+2){p.remove();emit(c);measure.append(p);if(measure.scrollWidth>measure.clientWidth+2){p.remove();let chunk='';for(const char of Array.from(line)){p=paragraph(chunk+char);p.style.margin='0 0 0 .6em';measure.replaceChildren(p);if(measure.scrollWidth>measure.clientWidth+2&&chunk){measure.replaceChildren(paragraph(chunk));emit(c);chunk=char}else chunk+=char}measure.replaceChildren(paragraph(chunk))}}}emit(c)}measure.remove();window.print()}
window.addEventListener('pagehide',save);document.addEventListener('visibilitychange',()=>{if(document.hidden)save()});window.addEventListener('beforeunload',e=>{if(dirty){save();if(dirty){e.preventDefault();e.returnValue=''}}});window.addEventListener('storage',e=>{if(e.key===KEY)toast('別のタブで更新がありました。同時編集を避け、バックアップを取ってください。')});render();

$('#editor').addEventListener('wheel',e=>{if(state.direction==='vertical'&&Math.abs(e.deltaY)>Math.abs(e.deltaX)){e.preventDefault();$('#editor').scrollLeft-=e.deltaY}},{passive:false});
$('#deleteChapter').onclick=()=>{const c=chapter();modal('章を削除','<p>'+esc(c.title)+'を削除します。削除前のバックアップを保存します。</p><button class="primary" id="confirmDelete">バックアップして削除</button>');$('#confirmDelete').onclick=()=>{download(JSON.stringify(state,null,2),'json','application/json');state.chapters=state.chapters.filter(x=>x.id!==active);if(!state.chapters.length)state.chapters.push({id:uid(),title:'新しい章',text:'',status:'未着手'});active=state.chapters[0].id;save();render();$('#dialog').close()}};
let selectedRange;document.addEventListener('selectionchange',()=>{const sel=window.getSelection();if(sel.rangeCount&&!sel.isCollapsed&&$('#editor').contains(sel.anchorNode)&&$('#editor').contains(sel.focusNode))selectedRange=sel.getRangeAt(0).cloneRange()});
$('#splitChapter').onmousedown=e=>e.preventDefault();$('#splitChapter').onclick=()=>{if(!selectedRange||!selectedRange.toString().trim())return toast('本文を選択してください');const text=selectedRange.toString();modal('選択範囲から章を作成','<label>章のタイトル</label><input id="splitTitle" value="新しい章"><button id="confirmSplit" class="primary">選択範囲を移動</button>');$('#confirmSplit').onclick=()=>{selectedRange.deleteContents();capture();const c={id:uid(),title:$('#splitTitle').value||'新しい章',text,status:'未着手'};state.chapters.splice(state.chapters.indexOf(chapter())+1,0,c);active=c.id;selectedRange=null;save();render();$('#dialog').close()}};
